import json
import os


def order_total(order):
    return sum(item["qty"] * item["price_cents"] for item in (order.get("items") or []))


def main():
    input_dir = os.environ["INPUT"]
    with open(os.path.join(input_dir, "orders.json"), encoding="utf-8") as f:
        orders = json.load(f)

    customers = {}  # name -> [paid order count, paid total cents]
    refunded_count = 0
    refunded_total = 0
    pending_count = 0

    for order in orders:
        status = order["status"]
        if status == "paid":
            entry = customers.setdefault(order["customer"], [0, 0])
            entry[0] += 1
            entry[1] += order_total(order)
        elif status == "refunded":
            refunded_count += 1
            refunded_total += order_total(order)
        elif status == "pending":
            pending_count += 1

    for name in sorted(customers, key=lambda s: s.encode("utf-8")):
        count, total = customers[name]
        print(f"{name} {count} {total}")

    print(f"refunded {refunded_count} {refunded_total}")
    print(f"pending {pending_count}")


if __name__ == "__main__":
    main()

import os


def normalize(line):
    s = line.strip().lower()
    if s.count("@") != 1:
        return None
    local, domain = s.split("@")
    if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
        return None
    if domain == "gmail.com":
        local = local.split("+", 1)[0].replace(".", "")
        if not local:
            return None
    return local + "@" + domain


def main():
    path = os.path.join(os.environ["INPUT"], "emails.txt")
    with open(path, encoding="utf-8", errors="replace") as f:
        lines = f.read().splitlines()

    valid = set()
    invalid = 0
    for line in lines:
        if not line.strip():
            continue
        result = normalize(line)
        if result is None:
            invalid += 1
        else:
            valid.add(result)

    for addr in sorted(valid, key=lambda x: x.encode("utf-8")):
        print(addr)
    print(f"invalid {invalid}")


if __name__ == "__main__":
    main()

import os
import re

ROMAN_TABLE = [
    (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
    (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
    (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
]
ROMAN_VAL = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
DECIMAL_RE = re.compile(r'[0-9]+')
ROMAN_RE = re.compile(r'[IVXLCDM]+')


def to_roman(n):
    parts = []
    for value, symbol in ROMAN_TABLE:
        while n >= value:
            parts.append(symbol)
            n -= value
    return ''.join(parts)


def from_roman(s):
    total = 0
    for i, ch in enumerate(s):
        v = ROMAN_VAL[ch]
        if i + 1 < len(s) and v < ROMAN_VAL[s[i + 1]]:
            total -= v
        else:
            total += v
    return total


def convert(value):
    if DECIMAL_RE.fullmatch(value):
        n = int(value)
        if 1 <= n <= 3999:
            return f"{value} = {to_roman(n)}"
        return f"{value} = invalid"
    if ROMAN_RE.fullmatch(value):
        n = from_roman(value)
        if 1 <= n <= 3999 and to_roman(n) == value:
            return f"{value} = {n}"
        return f"{value} = invalid"
    return f"{value} = invalid"


def main():
    input_dir = os.environ['INPUT']
    path = os.path.join(input_dir, 'numbers.txt')
    with open(path, encoding='utf-8') as f:
        lines = f.read().splitlines()
    for line in lines:
        value = line.strip()
        if not value:
            continue
        print(convert(value))


if __name__ == '__main__':
    main()

import os
import sys


def check(line):
    closers = {'(': ')', '[': ']', '{': '}'}
    partners = {')': '(', ']': '[', '}': '{'}
    stack = []
    for col, ch in enumerate(line, 1):
        if ch in closers:
            stack.append(ch)
        elif ch in partners:
            if not stack:
                return f"col {col}: unexpected {ch}"
            top = stack.pop()
            if top != partners[ch]:
                return f"col {col}: expected {closers[top]}, found {ch}"
    if stack:
        return f"unclosed {closers[stack[-1]]}"
    return "ok"


def main():
    path = os.path.join(os.environ["INPUT"], "snippets.txt")
    with open(path, "rb") as f:
        text = f.read().decode("latin-1")
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    out = []
    for line in lines:
        if line.endswith("\r"):
            line = line[:-1]
        out.append(check(line))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


if __name__ == "__main__":
    main()

import os
import re
import sys
from collections import defaultdict


def nearest_rank(sorted_times, p):
    n = len(sorted_times)
    rank = -(-p * n // 100)  # ceil(p * n / 100) using integer arithmetic
    return sorted_times[rank - 1]


def main():
    input_dir = os.environ["INPUT"]
    log_path = os.path.join(input_dir, "timings.log")

    int_pattern = re.compile(r"[+-]?[0-9]+")
    groups = defaultdict(list)

    try:
        with open(log_path, encoding="utf-8", errors="surrogateescape") as f:
            for line in f:
                fields = line.split()
                if len(fields) != 3:
                    continue
                method, path, millis = fields
                if not int_pattern.fullmatch(millis):
                    continue
                groups[(method, path)].append(int(millis))
    except FileNotFoundError:
        pass

    def byte_key(item):
        (method, path), _ = item
        return (
            method.encode("utf-8", "surrogateescape"),
            path.encode("utf-8", "surrogateescape"),
        )

    for (method, path), times in sorted(groups.items(), key=byte_key):
        times.sort()
        n = len(times)
        p50 = nearest_rank(times, 50)
        p95 = nearest_rank(times, 95)
        mx = times[-1]
        sys.stdout.write(
            f"{method} {path} count={n} p50={p50} p95={p95} max={mx}\n"
        )


if __name__ == "__main__":
    main()

import heapq
import os
import sys


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "routes.txt")

    adj = {}
    trips = []

    with open(path, encoding="utf-8") as f:
        for raw in f:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split()
            if parts[0] == "road" and len(parts) == 4:
                a, b = parts[1], parts[2]
                try:
                    c = int(parts[3])
                except ValueError:
                    continue
                adj.setdefault(a, {})
                adj.setdefault(b, {})
                for u, v in ((a, b), (b, a)):
                    if v not in adj[u] or c < adj[u][v]:
                        adj[u][v] = c
            elif parts[0] == "trip" and len(parts) == 3:
                trips.append((parts[1], parts[2]))

    cache = {}

    def dist_to(target):
        # Shortest distance from every town to `target` (graph is undirected).
        if target in cache:
            return cache[target]
        dist = {target: 0}
        pq = [(0, target)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in adj.get(u, {}).items():
                nd = d + w
                if v not in dist or nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        cache[target] = dist
        return dist

    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        dist = dist_to(y)
        if x not in dist:
            out.append(f"{x} {y} unreachable")
            continue
        # Greedily walk along shortest-path edges, always taking the
        # smallest next town; this yields the lexicographically smallest route.
        path_towns = [x]
        cur = x
        while cur != y:
            d = dist[cur]
            best = None
            for v, w in adj[cur].items():
                if v in dist and dist[v] + w == d:
                    if best is None or v < best:
                        best = v
            path_towns.append(best)
            cur = best
        out.append(f"{' -> '.join(path_towns)} {dist[x]}")

    if out:
        sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import json
import os
import sys


def strip_nulls(value):
    """Remove object keys whose value is null, recursively."""
    if isinstance(value, dict):
        return {k: strip_nulls(v) for k, v in value.items() if v is not None}
    if isinstance(value, list):
        return [strip_nulls(v) for v in value]
    return value


def merge(base, override):
    """Merge override into base. Both are expected to be objects."""
    if isinstance(base, dict) and isinstance(override, dict):
        result = dict(base)
        for key, value in override.items():
            if value is None:
                result.pop(key, None)
            elif isinstance(result.get(key), dict) and isinstance(value, dict):
                result[key] = merge(result[key], value)
            else:
                result[key] = strip_nulls(value)
        return result
    return strip_nulls(override)


def flatten(value, segments, out):
    if isinstance(value, dict):
        if not value:
            out.append((segments, "{}"))
            return
        for key, item in value.items():
            flatten(item, segments + [key], out)
    elif isinstance(value, list):
        if not value:
            out.append((segments, "[]"))
            return
        for index, item in enumerate(value):
            flatten(item, segments + [str(index)], out)
    else:
        out.append((segments, json.dumps(value)))


def load(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def main():
    input_dir = os.environ["INPUT"]
    base = load(os.path.join(input_dir, "base.json"))
    override = load(os.path.join(input_dir, "override.json"))

    merged = merge(base, override)

    leaves = []
    flatten(merged, [], leaves)

    rows = []
    for segments, rendered in leaves:
        path = ".".join(segments)
        rows.append((path, rendered))
    rows.sort(key=lambda row: row[0].encode("utf-8", "surrogatepass"))

    text = "".join(f"{path}={rendered}\n" for path, rendered in rows)
    sys.stdout.buffer.write(text.encode("utf-8", "surrogatepass"))
    sys.stdout.flush()


if __name__ == "__main__":
    main()

import os


def main():
    inp = os.environ["INPUT"]
    out = os.environ["OUT"]

    level_map = {"ERROR": "error", "WARN": "warn", "WARNING": "warn", "INFO": "info"}
    buckets = {"error": [], "warn": [], "info": []}
    counts = {"error": 0, "warn": 0, "info": 0, "other": 0}

    with open(os.path.join(inp, "app.log"), encoding="utf-8",
              errors="surrogateescape", newline="") as f:
        for raw in f:
            line = raw.rstrip("\r\n")
            if line.strip() == "":
                continue
            fields = [x for x in line.split(" ") if x]
            key = None
            if len(fields) >= 3:
                key = level_map.get(fields[1].upper())
            if key is None:
                counts["other"] += 1
            else:
                buckets[key].append(line)
                counts[key] += 1

    for key in ("error", "warn", "info"):
        path = os.path.join(out, key + ".log")
        with open(path, "w", encoding="utf-8",
                  errors="surrogateescape", newline="") as g:
            for line in buckets[key]:
                g.write(line + "\n")

    for key in ("error", "warn", "info", "other"):
        print(f"{key} {counts[key]}")


if __name__ == "__main__":
    main()

import os
import re


def main():
    indir = os.environ["INPUT"]
    outdir = os.environ["OUT"]

    part_pat = re.compile(r"part-[0-9]{4}\.txt")
    int_pat = re.compile(r"[+-]?[0-9]+")

    names = sorted(
        n for n in os.listdir(indir)
        if part_pat.fullmatch(n) and os.path.isfile(os.path.join(indir, n))
    )

    values = set()
    corrupt = 0

    for name in names:
        path = os.path.join(indir, name)
        try:
            with open(path, "rb") as f:
                text = f.read().decode("utf-8")
        except (OSError, UnicodeDecodeError):
            corrupt += 1
            continue

        part = []
        ok = True
        for raw in text.split("\n"):
            line = raw.strip()
            if not line:
                continue
            if not int_pat.fullmatch(line):
                ok = False
                break
            try:
                part.append(int(line))
            except ValueError:
                ok = False
                break

        if not ok:
            corrupt += 1
            continue

        values.update(part)

    out_values = sorted(values)
    with open(os.path.join(outdir, "merged.txt"), "w", encoding="utf-8", newline="\n") as f:
        for v in out_values:
            f.write(f"{v}\n")

    print(f"parts {len(names)} corrupt {corrupt} values {len(out_values)}")


if __name__ == "__main__":
    main()

import os
import shutil


def read_bytes(path):
    with open(path, "rb") as f:
        return f.read()


def same_contents(a, b):
    if os.path.getsize(a) != os.path.getsize(b):
        return False
    return read_bytes(a) == read_bytes(b)


def list_files(directory):
    return [n for n in os.listdir(directory)
            if os.path.isfile(os.path.join(directory, n))]


def main():
    src = os.environ["SRC"]
    dst = os.environ["DST"]

    src_names = sorted(list_files(src), key=os.fsencode)
    src_set = set(src_names)
    dst_set = set(list_files(dst))

    for name in src_names:
        s = os.path.join(src, name)
        d = os.path.join(dst, name)
        if name not in dst_set:
            shutil.copyfile(s, d)
            status = "added"
        elif same_contents(s, d):
            status = "same"
        else:
            shutil.copyfile(s, d)
            status = "updated"
        print(f"{status} {name}")

    kept = len(dst_set - src_set)
    print(f"kept {kept}")


if __name__ == "__main__":
    main()

import os
import json
import tempfile


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["COUNTS"]

    counts = {}
    if os.path.exists(kv_path) and os.path.getsize(kv_path) > 0:
        with open(kv_path, "r", encoding="utf-8") as f:
            counts = json.load(f)

    visits_path = os.path.join(input_dir, "visits.txt")
    with open(visits_path, "r", encoding="utf-8") as f:
        for line in f:
            page = line.strip()
            if page:
                counts[page] = counts.get(page, 0) + 1

    directory = os.path.dirname(os.path.abspath(kv_path))
    fd, tmp = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(counts, f)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, kv_path)
    except BaseException:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise

    for page, total in sorted(
        counts.items(),
        key=lambda kv: (-kv[1], kv[0].encode("utf-8")),
    ):
        print(f"{page} {total}")


if __name__ == "__main__":
    main()

import json
import os


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["USERS"]

    users = {}
    if os.path.exists(kv_path):
        with open(kv_path, "r", encoding="utf-8") as f:
            text = f.read()
        if text.strip():
            users = json.loads(text)

    commands_path = os.path.join(input_dir, "commands.txt")
    with open(commands_path, "r", encoding="utf-8") as f:
        lines = f.read().splitlines()

    out = []
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        cmd = parts[0]
        args = parts[1:]

        if cmd == "put" and len(args) == 3:
            uid, name, email = args
            users[uid] = [name, email]
            out.append(f"ok {uid}")
        elif cmd == "rename" and len(args) == 2:
            uid, name = args
            if uid in users:
                users[uid][0] = name
                out.append(f"ok {uid}")
            else:
                out.append(f"missing {uid}")
        elif cmd == "get" and len(args) == 1:
            uid = args[0]
            if uid in users:
                name, email = users[uid]
                out.append(json.dumps(
                    {"id": uid, "name": name, "email": email},
                    separators=(",", ":")))
            else:
                out.append(f"missing {uid}")
        elif cmd == "del" and len(args) == 1:
            uid = args[0]
            if uid in users:
                del users[uid]
                out.append(f"ok {uid}")
            else:
                out.append(f"missing {uid}")
        elif cmd == "count" and len(args) == 0:
            out.append(f"count {len(users)}")
        else:
            out.append(f"bad {line}")

    tmp_path = kv_path + ".tmp"
    parent = os.path.dirname(kv_path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(users, f, separators=(",", ":"))
    os.replace(tmp_path, kv_path)

    for line in out:
        print(line)


if __name__ == "__main__":
    main()

import json
import os


def load_state(path):
    if not os.path.exists(path):
        return {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def save_state(path, state):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f)
    os.replace(tmp, path)


def main():
    input_dir = os.environ["INPUT"]
    limits_path = os.environ["LIMITS"]

    state = load_state(limits_path)
    req_path = os.path.join(input_dir, "requests.txt")

    if os.path.exists(req_path):
        with open(req_path, "r", encoding="utf-8") as f:
            lines = f.readlines()
    else:
        lines = []

    for raw in lines:
        parts = raw.split()
        if len(parts) != 2:
            continue
        try:
            ts = int(parts[0])
        except ValueError:
            continue
        client = parts[1]
        window = ts // 60

        entry = state.get(client)
        if not (isinstance(entry, list) and len(entry) == 2 and entry[0] == window):
            entry = [window, 0]

        if entry[1] < 3:
            entry[1] += 1
            verdict = "allow"
        else:
            verdict = "deny"

        state[client] = entry
        print(f"{ts} {client} {verdict}")

    save_state(limits_path, state)


if __name__ == "__main__":
    main()

import os
import re
import sqlite3

MOVE_RE = re.compile(r'([+-])([0-9]+)\Z')
MAX_QTY = 2**63 - 1


class Reject(Exception):
    pass


def parse_move(token):
    m = MOVE_RE.match(token)
    if not m:
        return None
    n = int(m.group(2))
    if n < 1 or n > MAX_QTY:
        return None
    return n if m.group(1) == '+' else -n


def read_batches(path):
    try:
        with open(path, encoding='utf-8') as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        lines = []

    batches = []
    cur = None
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == 'batch' and len(parts) == 2:
            cur = {'name': parts[1], 'moves': [], 'bad': False}
            batches.append(cur)
            continue
        if len(parts) == 2:
            delta = parse_move(parts[1])
            if delta is not None:
                if cur is not None:
                    cur['moves'].append((parts[0], delta))
                continue
        if cur is not None:
            cur['bad'] = True
    return batches


def apply_batch(conn, name, moves):
    conn.execute('BEGIN IMMEDIATE')
    try:
        for sku, delta in moves:
            row = conn.execute(
                'SELECT qty FROM stock WHERE sku = ?', (sku,)
            ).fetchone()
            qty = (row[0] if row else 0) + delta
            if qty < 0 or qty > MAX_QTY:
                raise Reject()
            if row:
                conn.execute(
                    'UPDATE stock SET qty = ? WHERE sku = ?', (qty, sku)
                )
            else:
                conn.execute(
                    'INSERT INTO stock (sku, qty) VALUES (?, ?)', (sku, qty)
                )
        conn.execute('INSERT INTO applied (name) VALUES (?)', (name,))
        conn.execute('COMMIT')
        return True
    except Reject:
        conn.execute('ROLLBACK')
        return False
    except BaseException:
        conn.execute('ROLLBACK')
        raise


def main():
    input_dir = os.environ['INPUT']
    db_path = os.environ['STOCK']

    batches = read_batches(os.path.join(input_dir, 'moves.txt'))

    conn = sqlite3.connect(db_path, isolation_level=None)
    try:
        conn.execute(
            'CREATE TABLE IF NOT EXISTS stock '
            '(sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)'
        )
        conn.execute(
            'CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)'
        )
        done = {r[0] for r in conn.execute('SELECT name FROM applied')}

        for b in batches:
            name = b['name']
            if name in done:
                status = 'skipped'
            elif b['bad'] or not apply_batch(conn, name, b['moves']):
                status = 'rejected'
            else:
                done.add(name)
                status = 'applied'
            print(f'{name} {status}')

        rows = conn.execute(
            'SELECT sku, qty FROM stock WHERE qty <> 0'
        ).fetchall()
        for sku, qty in sorted(rows, key=lambda r: r[0].encode('utf-8')):
            print(f'{sku} {qty}')
    finally:
        conn.close()


if __name__ == '__main__':
    main()

import json
import os
import re
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

NAME_RE = re.compile(r"[a-z0-9-]{1,32}")
HIT_PREFIX = "/hit/"
COUNT_PREFIX = "/count/"


class KvStore:
    def __init__(self, path):
        self.path = path
        self.lock = threading.Lock()
        self.data = {}
        if os.path.exists(path) and os.path.getsize(path) > 0:
            with open(path, "r", encoding="utf-8") as f:
                self.data = json.load(f)

    def get(self, key):
        with self.lock:
            return self.data.get(key, 0)

    def incr(self, key):
        with self.lock:
            n = self.data.get(key, 0) + 1
            self.data[key] = n
            self._save()
            return n

    def top(self, k):
        with self.lock:
            items = sorted(self.data.items(), key=lambda kv: (-kv[1], kv[0]))
            return items[:k]

    def _save(self):
        tmp = self.path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(self.data, f)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, self.path)


class Req:
    def __init__(self, method, path):
        self.method = method
        self.path = path


class Res:
