NAME_RE = re.compile(r"[a-z0-9-]{1,32}")
HIT_PREFIX = "/hit/"
COUNT_PREFIX = "/count/"


class KvStore:
    def __init__(self, path):
        self.path = path
        self.lock = threading.Lock()
        self.data = {}
        if os.path.exists(path) and os.path.getsize(path) > 0:
            with open(path, "r", encoding="utf-8") as f:
                self.data = json.load(f)

    def get(self, key):
        with self.lock:
            return self.data.get(key, 0)

    def incr(self, key):
        with self.lock:
            n = self.data.get(key, 0) + 1
            self.data[key] = n
            self._save()
            return n

    def top(self, k):
        with self.lock:
            items = sorted(self.data.items(), key=lambda kv: (-kv[1], kv[0]))
            return items[:k]

    def _save(self):
        tmp = self.path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(self.data, f)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, self.path)


