import json
import os
import re
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlsplit

KV_PATH = os.environ.get("KV")
PORT = int(os.environ["PORT"])

ID_RE = re.compile(r"[1-9][0-9]*")
TODOS_PREFIX = "/todos/"

_lock = threading.Lock()
_db = {"next": 1, "todos": {}}


def load():
    if KV_PATH and os.path.exists(KV_PATH) and os.path.getsize(KV_PATH) > 0:
        with open(KV_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        _db["next"] = int(data["next"])
        _db["todos"] = {int(t["id"]): t for t in data["todos"]}


def save():
    if not KV_PATH:
        return
    data = {"next": _db["next"], "todos": list(_db["todos"].values())}
    tmp = KV_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, KV_PATH)


def parse_object(raw):
    try:
        obj = json.loads(raw.decode("utf-8"))
    except (ValueError, RecursionError):
        return None
    return obj if isinstance(obj, dict) else None


class Handler(BaseHTTPRequestHandler):
    server_version = "todo/1.0"
    sys_version = ""

    def log_message(self, format, *args):
        pass

    def read_body(self):
        try:
            if "chunked" in self.headers.get("Transfer-Encoding", "").lower():
                parts = []
                while True:
                    size = int(self.rfile.readline().split(b";")[0].strip(), 16)
                    if size == 0:
                        while self.rfile.readline() not in (b"\r\n", b"\n", b""):
                            pass
                        break
                    parts.append(self.rfile.read(size))
                    self.rfile.readline()
                return b"".join(parts)
            length = int(self.headers.get("Content-Length") or 0)
            return self.rfile.read(length) if length > 0 else b""
        except (ValueError, OSError):
            return b""

    def reply(self, status, obj=None):
        body = b"" if obj is None else json.dumps(obj).encode("utf-8")
        self.send_response(status)
        if obj is not None:
            self.send_header("Content-Type", "application/json")
        if status != 204:
            self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body and self.command != "HEAD":
            self.wfile.write(body)

    def handle_request(self):
        raw = self.read_body()
        parts = urlsplit(self.path)
        with _lock:
            self.route(self.command, parts.path, parse_qs(parts.query), raw)

    def route(self, method, path, query, raw):
        if path == "/todos":
            if method == "POST":
                return self.create(raw)
            if method == "GET":
                return self.list_todos(query)
        elif path.startswith(TODOS_PREFIX) and ID_RE.fullmatch(path[len(TODOS_PREFIX):]):
            tid = int(path[len(TODOS_PREFIX):])
            todo = _db["todos"].get(tid)
            if todo is not None:
                if method == "GET":
                    return self.reply(200, todo)
                if method == "PATCH":
                    return self.patch(todo, raw)
                if method == "DELETE":
                    del _db["todos"][tid]
                    save()
                    return self.reply(204)
        self.reply(404, {"error": "not found"})

    def create(self, raw):
        obj = parse_object(raw)
        title = obj.get("title") if obj is not None else None
        if not isinstance(title, str) or not title.strip():
            return self.reply(400, {"error": "title required"})
        todo = {"id": _db["next"], "title": title.strip(), "done": False}
        _db["next"] += 1
        _db["todos"][todo["id"]] = todo
        save()
        self.reply(201, todo)

    def list_todos(self, query):
        items = list(_db["todos"].values())
        done = query.get("done")
        if done and done[0] in ("true", "false"):
            want = done[0] == "true"
            items = [t for t in items if t["done"] is want]
        self.reply(200, items)

    def patch(self, todo, raw):
        bad = {"error": "bad update"}
        obj = parse_object(raw)
        if obj is None:
            return self.reply(400, bad)
        title, done = todo["title"], todo["done"]
        if "title" in obj:
            value = obj["title"]
            if not isinstance(value, str) or not value.strip():
                return self.reply(400, bad)
            title = value.strip()
        if "done" in obj:
            value = obj["done"]
            if not isinstance(value, bool):
                return self.reply(400, bad)
            done = value
        todo["title"], todo["done"] = title, done
        save()
        self.reply(200, todo)


for _m in ("GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS", "TRACE", "CONNECT"):
    setattr(Handler, "do_" + _m, Handler.handle_request)


def main():
    load()
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    print(f"listening on 127.0.0.1:{PORT}", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == "__main__":
    main()

import json
import os
import re
import sqlite3
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import parse_qs, urlsplit

SCHEMA = """
CREATE TABLE IF NOT EXISTS notes (
    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    body  TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS note_tags (
    note_id INTEGER NOT NULL REFERENCES notes(id),
    pos     INTEGER NOT NULL,
    tag     TEXT NOT NULL,
    PRIMARY KEY (note_id, tag)
);
CREATE INDEX IF NOT EXISTS note_tags_tag ON note_tags(tag);
"""

ID_RE = re.compile(r"[1-9][0-9]*")
MAX_ID_DIGITS = 18  # keeps ids within SQLite's 64-bit integer range

db = None  # shared SQLite connection, set in main()


def parse_id(segment):
    """Return the note id for a path segment, or None if malformed."""
    if len(segment) > MAX_ID_DIGITS or not ID_RE.fullmatch(segment):
        return None
    return int(segment)


def split_path(raw_path):
    return urlsplit(raw_path).path.split("/")


def normalize_tags(raw_tags):
    """Lowercase tags, dropping duplicates while keeping first-seen order."""
    result = []
    seen = set()
    for tag in raw_tags:
        tag = tag.lower()
        if tag not in seen:
            seen.add(tag)
            result.append(tag)
    return result


def load_note(note_id):
    row = db.execute(
        "SELECT id, title, body FROM notes WHERE id = ?", (note_id,)
    ).fetchone()
    if row is None:
        return None
    tags = [
        r[0]
        for r in db.execute(
            "SELECT tag FROM note_tags WHERE note_id = ? ORDER BY pos", (note_id,)
        )
    ]
    return {"id": row[0], "title": row[1], "body": row[2], "tags": tags}


class Handler(BaseHTTPRequestHandler):
    server_version = "NotesAPI/1.0"

    def _send(self, status, payload):
        data = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    def _not_found(self):
        self._send(404, {"error": "not found"})

    def _invalid_note(self):
        self._send(400, {"error": "invalid note"})

    def send_error(self, code, message=None, explain=None):
        # Unsupported methods get the API's own 404 instead of the stdlib 501.
        if code == HTTPStatus.NOT_IMPLEMENTED:
            return self._not_found()
        super().send_error(code, message, explain)

    def do_GET(self):
        url = urlsplit(self.path)
        segs = url.path.split("/")
        if segs == ["", "notes"]:
            return self._list_notes(url.query)
        if len(segs) == 3 and segs[1] == "notes":
            note_id = parse_id(segs[2])
            if note_id is not None:
                note = load_note(note_id)
                if note is not None:
                    return self._send(200, note)
        self._not_found()

    def _list_notes(self, query):
        params = parse_qs(query, keep_blank_values=True)
        sql = "SELECT n.id, n.title FROM notes n WHERE 1=1"
        args = []
        if "tag" in params:
            sql += (" AND EXISTS (SELECT 1 FROM note_tags t"
                    " WHERE t.note_id = n.id AND t.tag = ?)")
            args.append(params["tag"][0].lower())
        if "q" in params:
            word = params["q"][0]
            sql += " AND (instr(n.title, ?) > 0 OR instr(n.body, ?) > 0)"
            args += [word, word]
        sql += " ORDER BY n.id DESC"
        rows = db.execute(sql, args).fetchall()
        self._send(200, [{"id": i, "title": t} for i, t in rows])

    def do_POST(self):
        if split_path(self.path) != ["", "notes"]:
            return self._not_found()

        try:
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length > 0 else b""
            data = json.loads(raw.decode("utf-8"))
        except (ValueError, TypeError, RecursionError):
            return self._invalid_note()

        if not isinstance(data, dict):
            return self._invalid_note()

        title = data.get("title")
        body = data.get("body")
        tags = data.get("tags", [])

        if not isinstance(title, str) or title == "":
            return self._invalid_note()
        if not isinstance(body, str):
            return self._invalid_note()
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            return self._invalid_note()

        tags = normalize_tags(tags)

        with db:
            cur = db.execute(
                "INSERT INTO notes (title, body) VALUES (?, ?)", (title, body)
            )
            note_id = cur.lastrowid
            db.executemany(
                "INSERT INTO note_tags (note_id, pos, tag) VALUES (?, ?, ?)",
                [(note_id, pos, tag) for pos, tag in enumerate(tags)],
            )
        self._send(201, {"id": note_id})

    def do_DELETE(self):
        segs = split_path(self.path)
        if len(segs) == 3 and segs[1] == "notes":
            note_id = parse_id(segs[2])
            if note_id is not None:
                with db:
                    db.execute("DELETE FROM note_tags WHERE note_id = ?", (note_id,))
                    cur = db.execute("DELETE FROM notes WHERE id = ?", (note_id,))
                    found = cur.rowcount == 1
                if found:
                    return self._send(200, {"deleted": note_id})
        self._not_found()

    def log_message(self, format, *args):
        pass


def main():
    global db
    db = sqlite3.connect(os.environ["DB"])
    db.executescript(SCHEMA)
    db.commit()

    port = int(os.environ["PORT"])
    server = HTTPServer(("127.0.0.1", port), Handler)
    print(f"listening on 127.0.0.1:{port}", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        db.close()


if __name__ == "__main__":
    main()

import json
import os


def key(s):
    return s.encode("utf-8", "surrogatepass")


def sccs(nodes, adj):
    index = {}
    low = {}
    onstack = set()
    stack = []
    result = []
    counter = 0
    for root in nodes:
        if root in index:
            continue
        index[root] = low[root] = counter
        counter += 1
        stack.append(root)
        onstack.add(root)
        work = [(root, iter(adj[root]))]
        while work:
            v, it = work[-1]
            advanced = False
            for w in it:
                if w not in index:
                    index[w] = low[w] = counter
                    counter += 1
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, iter(adj[w])))
                    advanced = True
                    break
                elif w in onstack:
                    low[v] = min(low[v], index[w])
            if advanced:
                continue
            work.pop()
            if work:
                u = work[-1][0]
                low[u] = min(low[u], low[v])
            if low[v] == index[v]:
                comp = []
                while True:
                    w = stack.pop()
                    onstack.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                result.append(comp)
    return result


def main():
    base = os.environ["INPUT"]
    try:
        with open(os.path.join(base, "packages.json"), "r", encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError):
        print("error: not an object")
        return
    if not isinstance(data, dict):
        print("error: not an object")
        return

    # Valid packages and invalid entries
    valid = {}
    invalid = []
    for name, value in data.items():
        if isinstance(value, list) and all(isinstance(x, str) for x in value):
            valid[name] = set(value)
        else:
            invalid.append(name)

    # Missing dependencies: name -> packages that list it
    missing = {}
    for p, deps in valid.items():
        for d in deps:
            if d not in valid:
                missing.setdefault(d, set()).add(p)

    # Cycles via strongly connected components over valid packages
    adj = {p: [d for d in valid[p] if d in valid] for p in valid}
    cycle_groups = []
    cyclic = set()
    for comp in sccs(list(valid), adj):
        if len(comp) >= 2 or (len(comp) == 1 and comp[0] in valid[comp[0]]):
            group = sorted(comp, key=key)
            cycle_groups.append(group)
            cyclic.update(comp)
    cycle_groups.sort(key=lambda g: key(g[0]))

    # Built packages and stages (Kahn-style propagation)
    eligible = {
        p for p in valid
        if p not in cyclic and all(d in valid for d in valid[p])
    }
    pending = {p: len(valid[p]) for p in eligible}
    dependents = {}
    for p in eligible:
        for d in valid[p]:
            dependents.setdefault(d, []).append(p)

    stage = {}
    queue = []
    for p in eligible:
        if pending[p] == 0:
            stage[p] = 1
            queue.append(p)
    i = 0
    while i < len(queue):
        p = queue[i]
        i += 1
        for q in dependents.get(p, []):
            pending[q] -= 1
            if pending[q] == 0:
                stage[q] = 1 + max(stage[d] for d in valid[q])
                queue.append(q)

    out = []

    # Stage sections
    levels = {}
    for p, s in stage.items():
        levels.setdefault(s, []).append(p)
    for s in sorted(levels):
        names = sorted(levels[s], key=key)
        out.append(f"stage {s}: {', '.join(names)}")

    # Cycle sections
    for group in cycle_groups:
        out.append(f"cycle: {', '.join(group)}")

    # Missing sections
    for m in sorted(missing, key=key):
        needers = sorted(missing[m], key=key)
        out.append(f"missing: {m} (needed by {', '.join(needers)})")

    # Invalid section
    if invalid:
        out.append(f"invalid: {', '.join(sorted(invalid, key=key))}")

    # Blocked section: not built and in no cycle
    blocked = sorted(
        (p for p in valid if p not in stage and p not in cyclic), key=key
    )
    if blocked:
        out.append(f"blocked: {', '.join(blocked)}")

    out.append(f"built {len(stage)} of {len(valid)}")

    print("\n".join(out))


if __name__ == "__main__":
    main()

import os
import re
import sys


def to_min(s, is_end):
    m = re.fullmatch(r"([0-9]{2}):([0-9]{2})", s)
    if not m:
        return None
    h, mi = int(m.group(1)), int(m.group(2))
    if is_end and h == 24 and mi == 0:
        return 1440
    if h > 23 or mi > 59:
        return None
    return h * 60 + mi


def fmt(m):
    return f"{m // 60:02d}:{m % 60:02d}"


def kb(s):
    return s.encode("utf-8", "surrogateescape")


def main():
    inp = os.environ["INPUT"]
    path = os.path.join(inp, "bookings.csv")
    with open(path, "rb") as f:
        data = f.read().decode("utf-8", "surrogateescape")

    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()

    skipped = []
    seen = set()
    bookings = []  # (room, day, start, end, who)

    for idx, raw in enumerate(lines, start=1):
        if idx == 1:
            continue  # header
        line = raw[:-1] if raw.endswith("\r") else raw
        if line.strip() == "":
            continue
        fields = line.split(",")
        if len(fields) != 5:
            skipped.append(idx)
            continue
        room, day, st, en, who = fields
        s = to_min(st, False)
        e = to_min(en, True)
        if s is None or e is None or e <= s:
            skipped.append(idx)
            continue
        key = tuple(fields)
        if key in seen:
            continue
        seen.add(key)
        bookings.append((room, day, s, e, who))

    groups = {}
    for b in bookings:
        groups.setdefault((b[0], b[1]), []).append(b)

    out = []
    for room, day in sorted(groups, key=lambda k: (kb(k[0]), kb(k[1]))):
        items = groups[(room, day)]
        out.append(f"{room} {day}")

        # busy: merged intervals
        ivs = sorted((b[2], b[3]) for b in items)
        merged = []
        for s, e in ivs:
            if merged and s <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], e)
            else:
                merged.append([s, e])
        out.append("  busy " + ", ".join(f"{fmt(s)}-{fmt(e)}" for s, e in merged))

        # free: gaps >= 30 min within 09:00-18:00
        gaps = []
        cur = 540
        for s, e in merged:
            s2 = max(s, 540)
            e2 = min(e, 1080)
            if s2 >= e2:
                continue
            if s2 - cur >= 30:
                gaps.append((cur, s2))
            cur = max(cur, e2)
        if 1080 - cur >= 30:
            gaps.append((cur, 1080))
        if gaps:
            out.append("  free " + ", ".join(f"{fmt(s)}-{fmt(e)}" for s, e in gaps))
        else:
            out.append("  free none")

        # conflicts: pairs overlapping by at least one minute
        confs = []
        for i in range(len(items)):
            for j in range(i + 1, len(items)):
                a = items[i]
                b = items[j]
                os_ = max(a[2], b[2])
                oe = min(a[3], b[3])
                if oe - os_ >= 1:
                    names = sorted([a[4], b[4]], key=kb)
                    text = f"  conflict {names[0]}/{names[1]} {fmt(os_)}-{fmt(oe)}"
                    confs.append((os_, kb(text), text))
        confs.sort(key=lambda c: (c[0], c[1]))
        out.extend(c[2] for c in confs)

    if skipped:
        out.append("skipped: " + ", ".join(str(n) for n in skipped))
    else:
        out.append("skipped: none")

    text = "\n".join(out) + "\n"
    sys.stdout.buffer.write(text.encode("utf-8", "surrogateescape"))


if __name__ == "__main__":
    main()

import json
import os


def reject_constant(name):
    raise ValueError("invalid constant " + name)


def load(text):
    return json.loads(text, parse_constant=reject_constant)


def matches(t, v):
    if t == "object":
        return isinstance(v, dict)
    if t == "array":
        return isinstance(v, list)
    if t == "string":
        return isinstance(v, str)
    if t == "integer":
        return type(v) is int
    if t == "number":
        return isinstance(v, (int, float)) and not isinstance(v, bool)
    if t == "boolean":
        return isinstance(v, bool)
    if t == "null":
        return v is None
    return False


def check(schema, value, path, errs):
    t = schema["type"]
    if not matches(t, value):
        errs.append((path, "expected " + t))
        return

    if t == "object":
        props = schema.get("properties", {})
        for name in schema.get("required", []):
            if name not in value:
                errs.append((path + "." + name, "missing required field"))
        if schema.get("additional", True) is False:
            for name in value:
                if name not in props:
                    errs.append((path + "." + name, "unexpected field"))
        for name, sub in props.items():
            if name in value:
                check(sub, value[name], path + "." + name, errs)

    elif t == "array":
        mi = schema.get("min_items")
        if mi is not None and len(value) < mi:
            errs.append((path, "fewer than %d items" % mi))
        items = schema.get("items")
        if items is not None:
            for i, el in enumerate(value):
                check(items, el, "%s[%d]" % (path, i), errs)

    elif t == "string":
        n = len(value)
        if "min_length" in schema and n < schema["min_length"]:
            errs.append((path, "shorter than %d" % schema["min_length"]))
        elif "max_length" in schema and n > schema["max_length"]:
            errs.append((path, "longer than %d" % schema["max_length"]))
        elif "enum" in schema and value not in schema["enum"]:
            errs.append((path, "not in enum"))

    elif t in ("integer", "number"):
        if "minimum" in schema and value < schema["minimum"]:
            errs.append((path, "less than %s" % schema["minimum"]))
        elif "maximum" in schema and value > schema["maximum"]:
            errs.append((path, "greater than %s" % schema["maximum"]))


def sort_key(e):
    return (e[0].encode("utf-8", "surrogatepass"),
            e[1].encode("utf-8", "surrogatepass"))


def main():
    base = os.environ["INPUT"]
    with open(os.path.join(base, "schema.json"), "rb") as f:
        schema = load(f.read().decode("utf-8"))
    with open(os.path.join(base, "records.jsonl"), "rb") as f:
        data = f.read()

    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()

    total = 0
    valid = 0
    for n, raw in enumerate(lines, 1):
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            total += 1
            print("line %d: invalid JSON" % n)
            continue
        if text.strip() == "":
            continue
        total += 1
        try:
            rec = load(text)
        except ValueError:
            print("line %d: invalid JSON" % n)
            continue

        errs = []
        check(schema, rec, "$", errs)
        if not errs:
            valid += 1
            print("line %d: ok" % n)
        else:
            errs.sort(key=sort_key)
            for p, m in errs:
                print("line %d: %s: %s" % (n, p, m))

    print("valid %d of %d" % (valid, total))


if __name__ == "__main__":
    main()

import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

# No proxy: the API is an explicitly granted base URL.
OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))


def load_state(path):
    if not os.path.exists(path):
        return {}
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    if not text.strip():
        return {}
    data = json.loads(text)
    return data if isinstance(data, dict) else {}


def save_state(path, state):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f, sort_keys=True)
        f.flush()
    os.replace(tmp, path)


def send(url, body):
    """Return the HTTP status, or None if there was no response."""
    req = urllib.request.Request(
        url,
        data=body,
        method="PUT",
        headers={"content-type": "application/json"},
    )
    try:
        with OPENER.open(req, timeout=30) as resp:
            return resp.status
    except urllib.error.HTTPError as e:
        return e.code
    except Exception:
        return None


def push(api, rid, record):
    url = api + "/records/" + urllib.parse.quote(rid, safe="")
    body = json.dumps(record).encode("utf-8")
    for _ in range(3):
        code = send(url, body)
        if code is not None and 200 <= code < 300:
            return ("synced", None)
        if code is not None and 400 <= code < 500:
            return ("rejected", code)
        # 5xx, other statuses, or no response: retry
    return ("failed", None)


def parse_records(path):
    """Return (invalid line numbers, {id: (version, record)} with last valid line per id)."""
    with open(path, "rb") as f:
        raw = f.read()

    invalid = []
    latest = {}
    for n, chunk in enumerate(raw.split(b"\n"), start=1):
        try:
            text = chunk.decode("utf-8").strip()
        except UnicodeDecodeError:
            invalid.append(n)
            continue
        if text == "":
            continue
        try:
            rec = json.loads(text)
        except Exception:
            invalid.append(n)
            continue
        if (
            not isinstance(rec, dict)
            or not isinstance(rec.get("id"), str)
            or type(rec.get("version")) is not int
        ):
            invalid.append(n)
            continue
        latest[rec["id"]] = (rec["version"], rec)
    return invalid, latest


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"].rstrip("/")

    state = load_state(state_path)
    invalid, latest = parse_records(os.path.join(input_dir, "records.jsonl"))

    for n in invalid:
        print(f"line {n} invalid")

    results = {}
    for rid in sorted(latest, key=lambda s: s.encode("utf-8")):
        version, rec = latest[rid]
        last = state.get(rid)
        if isinstance(last, int) and version <= last:
            results[rid] = ("unchanged", None)
            continue

        outcome, detail = push(api, rid, rec)
        results[rid] = (outcome, detail)
        if outcome == "synced":
            state[rid] = version
            save_state(state_path, state)

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rid in sorted(results, key=lambda s: s.encode("utf-8")):
        outcome, detail = results[rid]
        counts[outcome] += 1
        if outcome == "rejected":
            print(f"{rid} rejected {detail}")
        else:
            print(f"{rid} {outcome}")

    print(
        f"synced {counts['synced']} unchanged {counts['unchanged']} "
        f"rejected {counts['rejected']} failed {counts['failed']}"
    )
    sys.stdout.flush()


if __name__ == "__main__":
    main()

import os
import re
import sqlite3
import sys
from datetime import datetime, timezone

MAX = 9223372036854775807
AMOUNT = re.compile(r'-?[0-9]+\Z')
DUP = object()


def fmt_time(ms):
    dt = datetime.fromtimestamp(ms // 1000, tz=timezone.utc)
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')


def amount(s):
    return int(s) if AMOUNT.match(s) else None


def get_open(conn, name):
    row = conn.execute(
        'SELECT balance FROM accounts WHERE name = ? AND open = 1', (name,)
    ).fetchone()
    return None if row is None else row[0]


def apply(conn, now, line):
    w = line.split(' ')
    op = w[0]

    if op == 'open':
        if len(w) != 3:
            return 'malformed'
        name = w[1]
        cents = amount(w[2])
        if cents is None:
            return 'malformed'
        if cents < 0:
            return 'bad amount'
        if conn.execute('SELECT 1 FROM accounts WHERE name = ?', (name,)).fetchone():
            return 'account exists'
        if cents > MAX:
            return 'overflow'
        conn.execute(
            'INSERT INTO accounts (name, balance, open, last) VALUES (?, ?, 1, ?)',
            (name, cents, now),
        )
        return None

    if op == 'transfer':
        if len(w) != 5:
            return 'malformed'
        tid, src, dst = w[1], w[2], w[3]
        cents = amount(w[4])
        if cents is None:
            return 'malformed'
        prev = conn.execute(
            'SELECT src, dst, cents FROM transfers WHERE id = ?', (tid,)
        ).fetchone()
        if prev is not None:
            return DUP if tuple(prev) == (src, dst, cents) else 'id reused'
        if cents <= 0:
            return 'bad amount'
        if src == dst:
            return 'same account'
        sbal = get_open(conn, src)
        if sbal is None:
            return 'no account ' + src
        dbal = get_open(conn, dst)
        if dbal is None:
            return 'no account ' + dst
        if sbal < cents:
            return 'insufficient funds'
        if dbal + cents > MAX:
            return 'overflow'
        conn.execute(
            'UPDATE accounts SET balance = balance - ?, last = ? WHERE name = ?',
            (cents, now, src),
        )
        conn.execute(
            'UPDATE accounts SET balance = balance + ?, last = ? WHERE name = ?',
            (cents, now, dst),
        )
        conn.execute(
            'INSERT INTO transfers (id, src, dst, cents) VALUES (?, ?, ?, ?)',
            (tid, src, dst, cents),
        )
        return None

    if op == 'close':
        if len(w) != 2:
            return 'malformed'
        name = w[1]
        bal = get_open(conn, name)
        if bal is None:
            return 'no account ' + name
        if bal != 0:
            return 'balance not zero'
        conn.execute('UPDATE accounts SET open = 0 WHERE name = ?', (name,))
        return None

    return 'malformed'


def main():
    inp = os.environ['INPUT']
    dbpath = os.environ['DB']
    logpath = os.environ['LOG']
    now = fmt_time(int(os.environ['CLOCK']))

    conn = sqlite3.connect(dbpath, isolation_level=None)
    conn.execute(
        'CREATE TABLE IF NOT EXISTS accounts ('
        'name TEXT PRIMARY KEY, balance INTEGER NOT NULL, '
        'open INTEGER NOT NULL, last TEXT NOT NULL)'
    )
    conn.execute(
        'CREATE TABLE IF NOT EXISTS transfers ('
        'id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, '
        'cents INTEGER NOT NULL)'
    )

    # latin-1 maps each byte to one code point, so byte order is preserved
    # exactly for sorting, storage and output.
    with open(os.path.join(inp, 'ops.txt'), 'rb') as f:
        text = f.read().decode('latin-1')
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines.pop()

    ok = failed = dup = 0
    with open(logpath, 'ab') as lf:
        for n, raw in enumerate(lines, 1):
            line = raw[:-1] if raw.endswith('\r') else raw
            if line.strip(' \t\r') == '':
                continue
            conn.execute('BEGIN IMMEDIATE')
            try:
                res = apply(conn, now, line)
            except BaseException:
                conn.execute('ROLLBACK')
                raise
            if res is None:
                conn.execute('COMMIT')
                ok += 1
            elif res is DUP:
                conn.execute('ROLLBACK')
                dup += 1
            else:
                conn.execute('ROLLBACK')
                failed += 1
                lf.write(f'{now} line {n}: {res}\n'.encode('latin-1'))
                lf.flush()

    rows = conn.execute(
        'SELECT name, balance, last FROM accounts WHERE open = 1'
    ).fetchall()
    rows.sort(key=lambda r: r[0])

    out = [f'ok {ok} failed {failed} duplicate {dup}']
    for name, bal, last in rows:
        out.append(f'{name} {bal} last {last}')
    sys.stdout.buffer.write(('\n'.join(out) + '\n').encode('latin-1'))
    sys.stdout.flush()

    conn.close()


if __name__ == '__main__':
    main()

import hashlib
import hmac
import json
import os
import re
import secrets
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

NAME_RE = re.compile(r"[a-z0-9_]{3,20}")
MAX_FAILS = 3
LOCK_MS = 15 * 60 * 1000
SESSION_MS = 30 * 60 * 1000
SESSION_SECONDS = 1800

STORE_PATH = os.environ.get("STORE") or "store.json"
PORT = int(os.environ.get("PORT", "8080"))
LOCK = threading.Lock()


def now_ms():
    raw = os.environ.get("CLOCK")
    if raw is not None and raw.strip():
        return int(raw)
    return int(time.time() * 1000)


def empty_state():
    return {"users": {}, "sessions": {}}


def load_state():
    if not os.path.exists(STORE_PATH):
        return empty_state()
    with open(STORE_PATH, "r", encoding="utf-8") as f:
        text = f.read()
    if not text.strip():
        return empty_state()
    data = json.loads(text)
    data.setdefault("users", {})
    data.setdefault("sessions", {})
    return data


def save_state(state):
    directory = os.path.dirname(os.path.abspath(STORE_PATH))
    os.makedirs(directory, exist_ok=True)
    tmp = STORE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, STORE_PATH)


def pw_bytes(pw):
    return pw.encode("utf-8", "surrogatepass")


def hash_password(salt_hex, pw):
    return hashlib.sha256(bytes.fromhex(salt_hex) + pw_bytes(pw)).hexdigest()


def parse_json_object(raw):
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return None
    return data if isinstance(data, dict) else None


def credentials(raw):
    data = parse_json_object(raw)
    if data is None:
        return None
    name = data.get("name")
    pw = data.get("password")
    if not isinstance(name, str) or not isinstance(pw, str):
        return None
    return name, pw


def signup(state, raw):
    creds = credentials(raw)
    if creds is None:
        return 400, {"error": "invalid"}
    name, pw = creds
    if not NAME_RE.fullmatch(name) or len(pw_bytes(pw)) < 8:
        return 400, {"error": "invalid"}
    if name in state["users"]:
        return 409, {"error": "name taken"}
    salt = secrets.token_bytes(16).hex()
    state["users"][name] = {
        "salt": salt,
        "hash": hash_password(salt, pw),
        "logins": 0,
        "fails": 0,
        "locked_until": 0,
    }
    return 201, {"name": name}


def login(state, raw, now):
    bad = (401, {"error": "bad credentials"})
    creds = credentials(raw)
    if creds is None:
        return bad
    name, pw = creds
    user = state["users"].get(name)
    if user is None:
        return bad
    if now < user["locked_until"]:
        return 429, {"error": "locked"}
    if not hmac.compare_digest(hash_password(user["salt"], pw), user["hash"]):
        user["fails"] += 1
        if user["fails"] >= MAX_FAILS:
            user["locked_until"] = now + LOCK_MS
            user["fails"] = 0
        return bad
    user["fails"] = 0
    user["logins"] += 1
    token = secrets.token_bytes(16).hex()
    state["sessions"][token] = {"name": name, "expires": now + SESSION_MS}
    return 200, {"token": token, "expires_in": SESSION_SECONDS}


def session_for(state, headers, now):
    header = headers.get("authorization")
    if not header:
        return None, None
    parts = header.strip().split(None, 1)
    if len(parts) != 2 or parts[0].lower() != "bearer":
        return None, None
    token = parts[1].strip()
    session = state["sessions"].get(token)
    if session is None:
        return None, None
    if now >= session["expires"]:
        del state["sessions"][token]
        return None, None
    return token, session


UNAUTHORIZED = (401, {"error": "unauthorized"})


def me(state, headers, now):
    _, session = session_for(state, headers, now)
    if session is None:
        return UNAUTHORIZED
    session["expires"] = now + SESSION_MS
    user = state["users"].get(session["name"])
    if user is None:
        return UNAUTHORIZED
    return 200, {"name": session["name"], "logins": user["logins"]}


def logout(state, headers, now):
    token, session = session_for(state, headers, now)
    if session is None:
        return UNAUTHORIZED
    del state["sessions"][token]
    return 204, None


def route(state, method, path, headers, raw, now):
    if method == "POST" and path == "/users":
        return signup(state, raw)
    if method == "POST" and path == "/login":
        return login(state, raw, now)
    if method == "GET" and path == "/me":
        return me(state, headers, now)
    if method == "POST" and path == "/logout":
        return logout(state, headers, now)
    return 404, {"error": "not found"}


class Handler(BaseHTTPRequestHandler):
    server_version = "sessions/1.0"

    def _serve(self, method):
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        path = self.path.split("?", 1)[0]

        with LOCK:
            now = now_ms()
            state = load_state()
            status, body = route(state, method, path, self.headers, raw, now)
            save_state(state)

        if status == 204 or body is None:
            self.send_response(status)
            self.send_header("Content-Length", "0")
            self.end_headers()
        else:
            data = json.dumps(body).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

    def do_GET(self):
        self._serve("GET")

    def do_POST(self):
        self._serve("POST")

    def do_PUT(self):
        self._serve("PUT")

    def do_PATCH(self):
        self._serve("PATCH")

    def do_DELETE(self):
        self._serve("DELETE")

    def log_message(self, format, *args):
        pass


def main():
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    print(f"listening on 127.0.0.1:{PORT}", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import json
import os
import re
import sqlite3
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlsplit

DB_PATH = os.environ["DB"]
PORT = int(os.environ["PORT"])

LOCK = threading.Lock()
CONN = sqlite3.connect(DB_PATH, check_same_thread=False, isolation_level=None)
CONN.executescript(
    """
    CREATE TABLE IF NOT EXISTS payments (
        seq INTEGER PRIMARY KEY AUTOINCREMENT,
        account TEXT NOT NULL,
        cents INTEGER NOT NULL,
        currency TEXT NOT NULL,
        status TEXT NOT NULL,
        refunded INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS payments_by_account ON payments (account, seq);
    CREATE TABLE IF NOT EXISTS idem (
        key TEXT PRIMARY KEY,
        method TEXT NOT NULL,
        path TEXT NOT NULL,
        body TEXT NOT NULL,
        status INTEGER NOT NULL,
        response TEXT NOT NULL
    );
    """
)

COLS = "seq, account, cents, currency, status, refunded"
NOT_FOUND = (404, json.dumps({"error": "not found"}))
MAX_SEQ = 2 ** 63 - 1


def err(status, msg):
    return status, json.dumps({"error": msg})


def valid_int(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, int):
        return True
    return isinstance(v, float) and v.is_integer()


def parse_body(raw):
    try:
        return json.loads(raw.decode("utf-8"))
    except Exception:
        return None


def normalize(v):
    if isinstance(v, dict):
        return {k: normalize(x) for k, x in v.items()}
    if isinstance(v, list):
        return [normalize(x) for x in v]
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v


def canonical(raw):
    try:
        v = json.loads(raw.decode("utf-8"))
    except Exception:
        return "!" + raw.hex()
    return json.dumps(normalize(v), sort_keys=True, separators=(",", ":"))


def parse_id(s):
    m = re.fullmatch(r"pay_([1-9][0-9]*)", s)
    if m is None:
        return None
    n = int(m.group(1))
    return n if n <= MAX_SEQ else None


def load(seq):
    if seq is None:
        return None
    return CONN.execute(f"SELECT {COLS} FROM payments WHERE seq = ?", (seq,)).fetchone()


def pay_json(row):
    seq, account, cents, currency, status, refunded = row
    return {
        "id": f"pay_{seq}",
        "account": account,
        "cents": cents,
        "currency": currency,
        "status": status,
        "refunded": refunded,
    }


def ok_payment(row, status=200):
    return status, json.dumps(pay_json(row))


def op_create(raw):
    body = parse_body(raw)
    if not isinstance(body, dict) or set(body) != {"account", "cents", "currency"}:
        return err(422, "invalid payment")
    account, cents, currency = body["account"], body["cents"], body["currency"]
    if not isinstance(account, str) or account == "":
        return err(422, "invalid payment")
    if not valid_int(cents) or cents <= 0:
        return err(422, "invalid payment")
    if not isinstance(currency, str) or currency not in ("EUR", "USD"):
        return err(422, "invalid payment")
    cur = CONN.execute(
        "INSERT INTO payments (account, cents, currency, status, refunded) "
        "VALUES (?, ?, ?, 'pending', 0)",
        (account, int(cents), currency),
    )
    return ok_payment(load(cur.lastrowid), 201)


def op_capture(seq):
    row = load(seq)
    if row is None:
        return NOT_FOUND
    if row[4] == "captured":
        return ok_payment(row)
    if row[4] != "pending":
        return err(409, "invalid transition")
    CONN.execute("UPDATE payments SET status = 'captured' WHERE seq = ?", (seq,))
    return ok_payment(load(seq))


def op_cancel(seq):
    row = load(seq)
    if row is None:
        return NOT_FOUND
    if row[4] != "pending":
        return err(409, "invalid transition")
    CONN.execute("UPDATE payments SET status = 'canceled' WHERE seq = ?", (seq,))
    return ok_payment(load(seq))


def op_refund(seq, raw):
    body = parse_body(raw)
    if not isinstance(body, dict) or not valid_int(body.get("cents")) or body["cents"] <= 0:
        return err(422, "invalid refund")
    n = int(body["cents"])
    row = load(seq)
    if row is None:
        return NOT_FOUND
    _, _, cents, _, status, refunded = row
    if status != "captured":
        return err(409, "invalid transition")
    if refunded + n > cents:
        return err(409, "exceeds captured")
    new_refunded = refunded + n
    new_status = "refunded" if new_refunded == cents else "captured"
    CONN.execute(
        "UPDATE payments SET refunded = ?, status = ? WHERE seq = ?",
        (new_refunded, new_status, seq),
    )
    return ok_payment(load(seq))


def idempotent(method, path, headers, raw, op):
    key = headers.get("idempotency-key")
    if not key:
        return err(400, "missing idempotency key")
    canon = canonical(raw)
    rec = CONN.execute(
        "SELECT method, path, body, status, response FROM idem WHERE key = ?",
        (key,),
    ).fetchone()
    if rec is not None:
        if rec[0] == method and rec[1] == path and rec[2] == canon:
            return rec[3], rec[4]
        return err(409, "key reused")
    status, text = op()
    if 200 <= status < 300:
        CONN.execute(
            "INSERT INTO idem (key, method, path, body, status, response) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (key, method, path, canon, status, text),
        )
    return status, text


def route(method, path, query, headers, raw):
    if path == "/payments":
        if method == "POST":
            return idempotent(method, path, headers, raw, lambda: op_create(raw))
        if method == "GET":
            accounts = parse_qs(query, keep_blank_values=True).get("account")
            if accounts is None:
                return NOT_FOUND
            rows = CONN.execute(
                f"SELECT {COLS} FROM payments WHERE account = ? ORDER BY seq",
                (accounts[0],),
            ).fetchall()
            return 200, json.dumps([pay_json(r) for r in rows])
        return NOT_FOUND

    m = re.fullmatch(r"/payments/([^/]+)(?:/(capture|cancel|refund))?", path)
    if m is None:
        return NOT_FOUND
    seq = parse_id(m.group(1))
    action = m.group(2)

    if action is None:
        if method == "GET":
            row = load(seq)
            return ok_payment(row) if row is not None else NOT_FOUND
        return NOT_FOUND

    if method != "POST":
        return NOT_FOUND
    if action == "refund":
        return idempotent(method, path, headers, raw, lambda: op_refund(seq, raw))
    if action == "capture":
        return op_capture(seq)
    return op_cancel(seq)


def process(method, path, query, headers, raw):
    with LOCK:
        CONN.execute("BEGIN IMMEDIATE")
        try:
            result = route(method, path, query, headers, raw)
        except BaseException:
            CONN.execute("ROLLBACK")
            raise
        CONN.execute("COMMIT")
        return result


class Handler(BaseHTTPRequestHandler):
    server_version = "payments"
    sys_version = ""

    def __getattr__(self, name):
        if name.startswith("do_"):
            return self._serve
        raise AttributeError(name)

    def _serve(self):
        try:
            length = int(self.headers.get("Content-Length", "0") or "0")
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        url = urlsplit(self.path)
        try:
            status, text = process(self.command, url.path, url.query, self.headers, raw)
        except Exception:
            status, text = 500, json.dumps({"error": "internal error"})
        data = text.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    def log_message(self, fmt, *args):
        pass


if __name__ == "__main__":
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    print(f"listening on 127.0.0.1:{PORT}", flush=True)
    server.serve_forever()

import hashlib
import json
import os
import re
import sys

DOCS = os.environ["DOCS"]
QUERIES = os.environ["QUERIES"]
INDEX = os.environ["INDEX"]

# Word bytes: ASCII letters and digits, plus every non-ASCII character.
# Undecodable bytes (surrogateescape) are non-ASCII too, so they fall in the same class.
WORD = re.compile('[0-9A-Za-z\u0080-\U0010ffff]+')


def out(line):
    sys.stdout.buffer.write((line + "\n").encode("utf-8", "surrogateescape"))


def bkey(s):
    return os.fsencode(s)


def words_of(text):
    # Split on the original text, then lowercase each word.
    return frozenset(m.lower() for m in WORD.findall(text))


def load_state():
    """Returns (files, postings).
    files:    path -> (sha256 hex, frozenset of words)
    postings: word -> set of paths
    """
    try:
        with open(INDEX, "r", encoding="utf-8") as f:
            st = json.load(f)
        files = {p: (v["hash"], frozenset(v["words"])) for p, v in st["files"].items()}
        postings = {w: set(ps) for w, ps in st["index"].items()}
        return files, postings
    except FileNotFoundError:
        return {}, {}
    except (OSError, ValueError, KeyError, TypeError, AttributeError):
        return {}, {}


def save_state(files, postings):
    st = {
        "files": {p: {"hash": h, "words": sorted(ws)} for p, (h, ws) in files.items()},
        "index": {w: sorted(ps, key=bkey) for w, ps in postings.items()},
    }
    tmp = INDEX + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(st, f)
    os.replace(tmp, INDEX)


def scan(old_files):
    """Returns path -> (digest, words). words is None when the file is unchanged."""
    current = {}
    for root, _dirs, names in os.walk(DOCS):
        for name in names:
            full = os.path.join(root, name)
            rel = os.path.relpath(full, DOCS).replace(os.sep, "/")
            with open(full, "rb") as f:
                data = f.read()
            digest = hashlib.sha256(data).hexdigest()
            old = old_files.get(rel)
            if old is not None and old[0] == digest:
                current[rel] = (digest, None)
            else:
                text = data.decode("utf-8", "surrogateescape")
                current[rel] = (digest, words_of(text))
    return current


def search(postings, qwords):
    # A query with no words matches nothing.
    if not qwords:
        return []
    common = None
    for w in qwords:
        s = postings.get(w)
        if not s:
            return []
        common = set(s) if common is None else common & s
        if not common:
            return []
    return sorted(common, key=bkey)


def main():
    files, postings = load_state()
    current = scan(files)

    events = []  # (path, kind)
    unchanged = 0

    for p in files:
        if p not in current:
            events.append((p, "removed"))

    for p, (digest, _words) in current.items():
        if p not in files:
            events.append((p, "added"))
        elif files[p][0] != digest:
            events.append((p, "changed"))
        else:
            unchanged += 1

    # Update the index: drop old postings for removed/changed files, add new ones.
    for p, kind in events:
        if p in files:
            for w in files[p][1]:
                s = postings.get(w)
                if s is not None:
                    s.discard(p)
                    if not s:
                        del postings[w]
            del files[p]
        if kind != "removed":
            digest, words = current[p]
            files[p] = (digest, words)
            for w in words:
                postings.setdefault(w, set()).add(p)

    events.sort(key=lambda e: bkey(e[0]))
    for p, kind in events:
        out(f"{kind} {p}")
    out(f"unchanged {unchanged}")

    save_state(files, postings)

    try:
        with open(os.path.join(QUERIES, "queries.txt"), "rb") as f:
            raw = f.read().decode("utf-8", "surrogateescape")
    except FileNotFoundError:
        raw = ""

    for line in raw.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if not line.strip():
            continue
        result = search(postings, words_of(line))
        if result:
            out(f"{line}: {', '.join(result)}")
        else:
            out(f"{line}: none")


if __name__ == "__main__":
    main()

import json
import os


def load_state(path):
    if not os.path.exists(path):
        return {}
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    jobs = data.get("jobs", {}) if isinstance(data, dict) else {}
    return jobs if isinstance(jobs, dict) else {}


def save_state(path, jobs):
    directory = os.path.dirname(os.path.abspath(path))
    os.makedirs(directory, exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump({"jobs": jobs}, f, sort_keys=True)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def load_script(path):
    if not os.path.exists(path):
        return {}
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    return data if isinstance(data, dict) else {}


def parse_job_line(line):
    try:
        obj = json.loads(line)
    except (ValueError, RecursionError):
        return None
    if not isinstance(obj, dict):
        return None
    jid = obj.get("id")
    prio = obj.get("priority")
    if not isinstance(jid, str):
        return None
    if not isinstance(prio, int) or isinstance(prio, bool):
        return None
    return jid, prio


def enqueue(path, jobs, now):
    if not os.path.exists(path):
        return
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for n, line in enumerate(f, 1):
            if line.strip() == "":
                continue
            parsed = parse_job_line(line)
            if parsed is None:
                print(f"invalid line {n}")
                continue
            jid, prio = parsed
            if jid in jobs:
                print("duplicate ID")
                continue
            jobs[jid] = {
                "priority": prio,
                "due": now,
                "attempts": 0,
                "state": "pending",
            }


def run_jobs(jobs, now, script):
    due = [
        jid
        for jid, job in jobs.items()
        if job["state"] == "pending" and job["due"] <= now
    ]
    due.sort(key=lambda jid: (-jobs[jid]["priority"], jobs[jid]["due"], jid.encode("utf-8")))

    for jid in due[:5]:
        job = jobs[jid]
        outcomes = script.get(jid)
        if isinstance(outcomes, list) and outcomes:
            idx = min(job["attempts"], len(outcomes) - 1)
            outcome = outcomes[idx]
        else:
            outcome = "ok"

        job["attempts"] += 1

        if outcome == "fail":
            if job["attempts"] >= 4:
                job["state"] = "dead"
                print(f"dead {jid}")
            else:
                backoff = 60 * (2 ** (job["attempts"] - 1))
                job["due"] = now + backoff * 1000
                print(f"retry {jid} in {backoff}")
        else:
            job["state"] = "done"
            print(f"done {jid}")


def main():
    input_dir = os.environ["INPUT"]
    queue_path = os.environ["QUEUE"]
    now = int(os.environ["CLOCK"])

    jobs = load_state(queue_path)
    enqueue(os.path.join(input_dir, "enqueue.jsonl"), jobs, now)
    script = load_script(os.path.join(input_dir, "script.json"))
    run_jobs(jobs, now, script)
    save_state(queue_path, jobs)

    counts = {"pending": 0, "done": 0, "dead": 0}
    for job in jobs.values():
        counts[job["state"]] += 1
    print(f"pending {counts['pending']} done {counts['done']} dead {counts['dead']}")


if __name__ == "__main__":
    main()

