        while self.peek() in ("+", "-"):
            op = self.take()[0]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.peek() in ("*", "/", "%"):
            op = self.take()[0]
            node = ("bin", op, node, self.factor())
        return node

    def factor(self):
        if self.peek() == "-":
            self.take()
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.peek() == "^":
            self.take()
            return ("pow", a, self.factor())
        return a

    def atom(self):
        k = self.peek()
        if k == "INT":
            return ("num", self.take()[1])
        if k == "NAME":
            name = self.take()[1]
            if self.peek() == "(":
                self.take()
                args = [self.expr()]
                while self.peek() == ",":
                    self.take()
                    args.append(self.expr())
                self.expect(")")
                return ("call", name, args)
            return ("var", name)
        if k == "(":
            self.take()
            e = self.expr()
            self.expect(")")
            return e
        raise Err("syntax error")


def parse(line):
    toks = tokenize(line)
    p = Parser(toks)
    if toks and toks[0] == ("NAME", "let"):
        p.i = 1
        name = p.take("NAME")[1]
        p.expect("=")
        e = p.expr()
        p.end()
        return ("let", name, e)
    e = p.expr()
    p.end()
    return ("expr", e)


def chk(v):
    if v < MIN or v > MAX:
        raise Err("overflow")
    return v


def lit(s):
    t = s.lstrip("0") or "0"
    if len(t) > 19 or int(t) > MAX:
        raise Err("overflow")
    return int(t)


def powi(a, b):
    if a == 0:
        return 1 if b == 0 else 0
    if a == 1:
        return 1
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b > 64:
        raise Err("overflow")
    return chk(a ** b)


def _abs(a):
    return chk(abs(a))


FUNCS = {
    "min": (2, min),
    "max": (2, max),
    "abs": (1, _abs),
}


def ev(node, env):
    k = node[0]
    if k == "num":
        return lit(node[1])
    if k == "var":
        name = node[1]
        if name not in env:
            raise Err(f"unknown variable {name}")
        return env[name]
    if k == "neg":
        return chk(-ev(node[1], env))
    if k == "pow":
        a = ev(node[1], env)
        b = ev(node[2], env)
        if b < 0:
            raise Err("negative exponent")
        return powi(a, b)
    if k == "bin":
        op = node[1]
        a = ev(node[2], env)
        b = ev(node[3], env)
        if op == "+":
            return chk(a + b)
        if op == "-":
            return chk(a - b)
        if op == "*":
            return chk(a * b)
        # "/" or "%": truncate toward zero
        if b == 0:
            raise Err("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        if op == "/":
            return chk(q)
        r = abs(a) % abs(b)
        return -r if a < 0 else r
    if k == "call":
        name, args = node[1], node[2]
        if name not in FUNCS:
            raise Err(f"unknown function {name}")
        arity, fn = FUNCS[name]
        if len(args) != arity:
            raise Err(f"wrong number of arguments to {name}")
        vals = [ev(x, env) for x in args]
        return fn(*vals)
    raise Err("syntax error")


def main():
    d = os.environ["INPUT"]
    path = os.path.join(d, "program.txt")
    with open(path, "rb") as f:
        text = f.read().decode("latin-1")

    out = []
    env = {}
    n = 0
    for raw in text.split("\n"):
        line = raw.rstrip("\r")
        if line.strip(" ") == "":
            continue
        n += 1
        try:
            stmt = parse(line)
            if stmt[0] == "let":
                v = ev(stmt[2], env)
                env[stmt[1]] = v
                out.append(f"{n}: {stmt[1]} = {v}")
            else:
                out.append(f"{n}: {ev(stmt[1], env)}")
        except Err as e:
            out.append(f"{n}: error: {e.msg}")

    if out:
        sys.stdout.write("\n".join(out) + "\n")
    sys.stdout.flush()


if __name__ == "__main__":
    sys.setrecursionlimit(1000000)
    threading.stack_size(256 * 1024 * 1024)
    t = threading.Thread(target=main)
    t.start()
    t.join()

import os
import sys
