MIN = -(1 << 63)
MAX = (1 << 63) - 1
DIGITS = "0123456789"
LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
IDCHARS = LETTERS + DIGITS + "_"
OPS = "+-*/%^(),="


class Err(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == " ":
            i += 1
        elif c in DIGITS:
            j = i
            while j < n and s[j] in DIGITS:
                j += 1
            toks.append(("INT", s[i:j]))
            i = j
        elif c in LETTERS or c == "_":
            j = i
            while j < n and s[j] in IDCHARS:
                j += 1
            toks.append(("NAME", s[i:j]))
            i = j
        elif c in OPS:
            toks.append((c, c))
            i += 1
        else:
            raise Err("syntax error")
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i][0] if self.i < len(self.t) else None

    def take(self, kind=None):
        if self.i >= len(self.t):
            raise Err("syntax error")
        tok = self.t[self.i]
        if kind is not None and tok[0] != kind:
            raise Err("syntax error")
        self.i += 1
        return tok

    def expect(self, kind):
        self.take(kind)

    def end(self):
        if self.i != len(self.t):
            raise Err("syntax error")

    def expr(self):
        node = self.term()
        while self.peek() in ("+", "-"):
            op = self.take()[0]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.peek() in ("*", "/", "%"):
            op = self.take()[0]
            node = ("bin", op, node, self.factor())
        return node

    def factor(self):
        if self.peek() == "-":
            self.take()
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.peek() == "^":
            self.take()
            return ("pow", a, self.factor())
        return a

    def atom(self):
        k = self.peek()
        if k == "INT":
            return ("num", self.take()[1])
        if k == "NAME":
            name = self.take()[1]
            if self.peek() == "(":
                self.take()
                args = [self.expr()]
                while self.peek() == ",":
                    self.take()
                    args.append(self.expr())
                self.expect(")")
                return ("call", name, args)
            return ("var", name)
        if k == "(":
            self.take()
            e = self.expr()
            self.expect(")")
            return e
        raise Err("syntax error")


def parse(line):
    toks = tokenize(line)
    p = Parser(toks)
    if toks and toks[0] == ("NAME", "let"):
        p.i = 1
        name = p.take("NAME")[1]
        p.expect("=")
        e = p.expr()
        p.end()
        return ("let", name, e)
    e = p.expr()
    p.end()
    return ("expr", e)


def chk(v):
    if v < MIN or v > MAX:
        raise Err("overflow")
    return v


def lit(s):
    t = s.lstrip("0") or "0"
    if len(t) > 19 or int(t) > MAX:
