        raise Err("overflow")
    return chk(a ** b)


def _abs(a):
    return chk(abs(a))


FUNCS = {
    "min": (2, min),
    "max": (2, max),
    "abs": (1, _abs),
}


def ev(node, env):
    k = node[0]
    if k == "num":
        return lit(node[1])
    if k == "var":
        name = node[1]
        if name not in env:
            raise Err(f"unknown variable {name}")
        return env[name]
    if k == "neg":
