import hashlib
import hmac
import json
import os
import sqlite3
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

TYPES = {
    "subscription.created",
    "subscription.activated",
    "payment.failed",
    "subscription.canceled",
}

TRANS = {
    ("subscription.created", "none"): "created",
    ("subscription.activated", "created"): "active",
    ("subscription.activated", "past_due"): "active",
    ("payment.failed", "active"): "past_due",
    ("subscription.canceled", "created"): "canceled",
    ("subscription.canceled", "active"): "canceled",
    ("subscription.canceled", "past_due"): "canceled",
}

SCHEMA = """
CREATE TABLE IF NOT EXISTS events (
    id TEXT PRIMARY KEY,
    sub TEXT NOT NULL,
    seq INTEGER NOT NULL,
    type TEXT NOT NULL,
    status TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS events_sub_seq ON events (sub, seq, status);
CREATE TABLE IF NOT EXISTS subs (
    id TEXT PRIMARY KEY,
    state TEXT NOT NULL,
    seq INTEGER NOT NULL,
    history TEXT NOT NULL
);
"""

LOCK = threading.Lock()
CON = None


def load_secret():
    with open(os.path.join(os.environ["SECRETS"], "webhook.key"), "rb") as f:
        data = f.read()
    if data.endswith(b"\n"):
        data = data[:-1]
        if data.endswith(b"\r"):
            data = data[:-1]
    return data


def log_line(msg):
    # Caller must hold LOCK when called from request processing.
    with open(os.environ["LOG"], "a", encoding="utf-8") as f:
        f.write(msg + "\n")


def valid(ev):
    if not isinstance(ev, dict):
        return False
    i, t, s, q = ev.get("id"), ev.get("type"), ev.get("subscription"), ev.get("seq")
    return (
        isinstance(i, str)
        and isinstance(t, str)
        and t in TYPES
        and isinstance(s, str)
        and isinstance(q, int)
        and not isinstance(q, bool)
        and q >= 1
    )


def step(state, history, typ, eid):
    new = TRANS.get((typ, state))
    if new is None:
        log_line(f"invalid transition {eid}")
        return state, history
    return new, history + [new]


def _process(con, eid, typ, sub, seq):
    if con.execute("SELECT 1 FROM events WHERE id=?", (eid,)).fetchone():
        return 200, {"status": "duplicate"}

    row = con.execute(
        "SELECT state, seq, history FROM subs WHERE id=?", (sub,)
    ).fetchone()
    if row:
        state, last, history = row[0], row[1], json.loads(row[2])
    else:
        state, last, history = "none", 0, []

    if seq <= last:
        con.execute(
            "INSERT INTO events (id, sub, seq, type, status) VALUES (?,?,?,?,?)",
            (eid, sub, seq, typ, "stale"),
        )
        return 200, {"status": "stale"}

    if seq > last + 1:
        con.execute(
            "INSERT INTO events (id, sub, seq, type, status) VALUES (?,?,?,?,?)",
            (eid, sub, seq, typ, "queued"),
        )
        return 202, {"status": "queued"}

    # seq == last + 1: apply it, then every kept event that now follows.
    con.execute(
        "INSERT INTO events (id, sub, seq, type, status) VALUES (?,?,?,?,?)",
        (eid, sub, seq, typ, "applied"),
    )
    state, history = step(state, history, typ, eid)
    last = seq
    applied = 1

    while True:
        nxt = con.execute(
            "SELECT id, type FROM events WHERE sub=? AND seq=? AND status='queued' "
            "ORDER BY rowid LIMIT 1",
            (sub, last + 1),
        ).fetchone()
        if nxt is None:
            break
        con.execute("UPDATE events SET status='applied' WHERE id=?", (nxt[0],))
        # Any other kept event with the same seq is superseded by the one applied.
        con.execute(
            "UPDATE events SET status='stale' WHERE sub=? AND seq=? AND status='queued'",
            (sub, last + 1),
        )
        state, history = step(state, history, nxt[1], nxt[0])
        last += 1
        applied += 1

    con.execute(
        "INSERT OR REPLACE INTO subs (id, state, seq, history) VALUES (?,?,?,?)",
        (sub, state, last, json.dumps(history)),
    )
    return 200, {"status": "applied", "applied": applied}


def process(ev):
    eid, typ, sub, seq = ev["id"], ev["type"], ev["subscription"], ev["seq"]
    with LOCK:
        con = CON
        con.execute("BEGIN IMMEDIATE")
        try:
            result = _process(con, eid, typ, sub, seq)
            con.execute("COMMIT")
            return result
        except BaseException:
            con.execute("ROLLBACK")
            raise


def get_sub(sid):
    with LOCK:
        row = CON.execute(
            "SELECT state, seq, history FROM subs WHERE id=?", (sid,)
        ).fetchone()
    if row is None:
        return 404, {"error": "not found"}
    return 200, {
        "id": sid,
        "state": row[0],
        "seq": row[1],
        "history": json.loads(row[2]),
    }


class H(BaseHTTPRequestHandler):
    def _send(self, code, obj):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def not_found(self):
        self._send(404, {"error": "not found"})

    def do_POST(self):
        try:
            n = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            n = 0
        body = self.rfile.read(n) if n > 0 else b""

        if urlsplit(self.path).path != "/webhooks":
            return self._send(404, {"error": "not found"})

        sig = self.headers.get("x-signature")
        expected = "sha256=" + hashlib.sha256(
            load_secret() + b"." + body
        ).hexdigest()
        ok = sig is not None and hmac.compare_digest(
            sig.encode("utf-8"), expected.encode("utf-8")
        )
        if not ok:
            with LOCK:
                log_line("rejected signature")
            return self._send(401, {"error": "bad signature"})

        try:
            ev = json.loads(body)
        except ValueError:
            ev = None
        if not valid(ev):
            return self._send(400, {"error": "invalid event"})

        code, obj = process(ev)
        self._send(code, obj)

    def do_GET(self):
        parts = urlsplit(self.path).path.split("/")
        if len(parts) == 3 and parts[1] == "subscriptions" and parts[2]:
            code, obj = get_sub(unquote(parts[2]))
            return self._send(code, obj)
        self._send(404, {"error": "not found"})

    do_PUT = do_DELETE = do_PATCH = do_OPTIONS = not_found

    def log_message(self, format, *args):
        pass


def main():
    global CON
    CON = sqlite3.connect(
        os.environ["DB"], isolation_level=None, check_same_thread=False
    )
    CON.executescript(SCHEMA)
    port = int(os.environ["PORT"])
    srv = ThreadingHTTPServer(("127.0.0.1", port), H)
    print(f"listening on 127.0.0.1:{port}", flush=True)
    srv.serve_forever()


if __name__ == "__main__":
    main()
